  const path = stateFile();
  await mkdir(dirname(path), { recursive: true });
  const tmp = path + "." + process.pid + "." + Date.now() + ".tmp";
  await writeFile(tmp, JSON.stringify(state, null, 2), "utf8");
  await rename(tmp, path);
}
var settingsStoreRead;
async function persistSettingsFromStore() {
  if (!settingsStoreRead)
    return;
  const st = await readState();
  const settings = sanitizeSettings(settingsStoreRead());
  if (JSON.stringify(st.settings) === JSON.stringify(settings))
    return;
  st.settings = settings;
  await writeState(st);
}
var agentsService;
var sessionQueryService;
function titleOfAgent(agent) {
  const events = agent?.session?.events;
  if (!Array.isArray(events))
    return void 0;
  for (let index = events.length - 1; index >= 0; index -= 1) {
    const event = events[index];
    if (event?.type === "session/title" && typeof event.data?.title === "string") {
      const title = event.data.title.trim();
      return title.length > 0 ? title : void 0;
    }
  }
  return void 0;
}
async function handler(endpoint, payload) {
  try {
    switch (endpoint) {
      case "health":
        return { ok: true, value: { ok: true, plugin: "dsh-idle-archive" } };
      case "state": {
        const st = await readState();
        return { ok: true, value: { settings: st.settings, snoozed: st.snoozed } };
      }
      case "config": {
        const st = await readState();
        const settings = sanitizeSettings(payload && payload.settings);
        st.settings = settings;
        await writeState(st);
        return { ok: true, value: { settings } };
      }
      case "snooze": {
        const id = payload && typeof payload.sessionId === "string" ? payload.sessionId : "";
        const hours = payload && typeof payload === "object" && Number.isFinite(payload.hours) ? payload.hours : 24;
        if (!id)
          return { ok: false, error: { code: "bad-args", details: "sessionId required" } };
        const st = await readState();
        st.snoozed[id] = Date.now() + Math.min(24 * 30, Math.max(1, Math.round(hours))) * 36e5;
        await writeState(st);
        return { ok: true, value: { snoozed: st.snoozed } };
      }
      case "snoozeMany": {
        const ids = Array.isArray(payload && payload.sessionIds) ? payload.sessionIds : [];
        const hours = payload && typeof payload === "object" && Number.isFinite(payload.hours) ? payload.hours : 24;
        if (ids.length === 0)
          return { ok: false, error: { code: "bad-args", details: "sessionIds required" } };
        const st = await readState();
        const until = Date.now() + Math.min(24 * 30, Math.max(1, Math.round(hours))) * 36e5;
        for (const id of ids) {
          if (typeof id === "string" && id)
            st.snoozed[id] = until;
        }
        await writeState(st);
        return { ok: true, value: { snoozed: st.snoozed } };
      }
      case "clearSnooze": {
        const id = payload && typeof payload.sessionId === "string" ? payload.sessionId : "";
        if (!id)
          return { ok: false, error: { code: "bad-args", details: "sessionId required" } };
        const st = await readState();
        delete st.snoozed[id];
        await writeState(st);
        return { ok: true, value: { snoozed: st.snoozed } };
      }
      case "titles": {
        const ids = Array.isArray(payload && payload.sessionIds) ? payload.sessionIds : [];
        const wanted = new Set(ids.filter((x) => typeof x === "string"));
        const titles = {};
        if (sessionQueryService && wanted.size > 0) {
          for (const id of wanted) {
            try {
              const snapshot = await sessionQueryService.readTitle(id);
              const title = snapshot?.title;
              if (typeof title === "string" && title !== "")
                titles[id] = title;
            } catch {
            }
          }
        }
        if (agentsService && wanted.size > 0) {
          for (const agent of agentsService.list()) {
            const id = agent?.session?.id;
            if (typeof id !== "string" || !wanted.has(id) || titles[id] !== void 0)
              continue;
            const title = titleOfAgent(agent);
            if (title !== void 0)
              titles[id] = title;
          }
        }
        return { ok: true, value: { titles } };
      }
      default:
        return { ok: false, error: { code: "unknown", details: String(endpoint) } };
    }
  } catch (e) {
    return { ok: false, error: { code: "error", details: String(e?.message || e) } };
  }
}
function apply(ctx, config = {}) {
  ctx.inject(["connection", "agents", "sessionQuery"], (connectionCtx) => {
    agentsService = connectionCtx.agents;
    sessionQueryService = connectionCtx.sessionQuery;
    connectionCtx.effect(() => connectionCtx.connection.rpc.handle(CHANNEL, handler, { authority: "loopback" }), "dsh-idle-archive: rpc");
  });
  const routeDisposer = ctx.webServer.register({
    path: ROUTES.health,
    kind: "exact",
    handler(req, res) {
      if (!isLoopbackRequest(req))
        return writeJson(res, 403, { error: "forbidden: loopback-only" });
      if (req.method !== "GET")
        return writeJson(res, 405, { error: "method not allowed: " + req.method });
      writeJson(res, 200, { ok: true, plugin: "dsh-idle-archive" });
    }
  });
  installSettingsNamespace(ctx, "dsh-idle-archive", Config, config ?? {}, {
    setSource: (source) => {
      settingsStoreRead = source;
    },
    onChange: () => {
      void persistSettingsFromStore();
    }
  });
  ctx.effect(() => () => {
    try {
      routeDisposer();
    } catch {
    }
  }, "dsh-idle-archive");
}
export {
  CHANNEL,
  Config,
  ROUTES,
  apply,
  defaultSettings,
  handler,
  inject,
  isLoopbackRequest,
  name,
  readState,
  sanitizeSettings,
  stateFile,
  titleOfAgent,
  writeJson,
  writeState
};

